#!/usr/bin/env python3
import csv,hashlib,json,math
from pathlib import Path
H=Path(__file__).resolve().parent;O=H/"results";C=json.loads((O/"UAV_V41_FROZEN_CONTRACT.json").read_text());b={k:C[k] for k in C if k!="contract_sha256"};h=hashlib.sha256(json.dumps(b,sort_keys=True,separators=(",",":")).encode()).hexdigest();r=list(csv.DictReader((O/"uav_v41_term_breakdown.csv").open()));checks={"hash":h==C["contract_sha256"],"no_heldout":C["heldout_seed_count_read"]==0,"successful_reset_error_separated":C["Ep_m"]<0.05,"growth_nonnegative":C["Vph_m"]>=0 and C["Vvh_mps"]>=0,"all_terms_finite":all(math.isfinite(float(x[k])) for x in r for k in ("force_m","position_info_m","velocity_info_m","peak_m","ultimate_m")),"rows":len(r)==32};R={"checks":checks,"valid":all(checks.values()),"contract_sha256":C["contract_sha256"],"feasible_rho":C["feasible_rho"]};(O/"uav_v41_validation.json").write_text(json.dumps(R,indent=2)+"\n");print(json.dumps(R,indent=2));raise SystemExit(0 if R["valid"] else 2)
